def check_state(sess):
    try:
        pages = sess.context.pages
        return {"context_ok": True, "n_pages": len(pages),
                "urls": [p.url for p in pages if not p.is_closed()],
                "page_closed": sess.page.is_closed()}
    except Exception as e:
        return {"context_ok": False, "error": str(e)}

print(bm._run(check_state))

def adopt_live_page(sess):
    for p in sess.context.pages:
        if not p.is_closed():
            sess.page = p
            return p.url
    newp = sess.context.new_page()
    sess.page = newp
    return newp.url
print(bm._run(adopt_live_page))
